    $('#knob-save').onclick = async () => { let n = 0; for (const el of document.querySelectorAll('[data-knob]')) { const k = el.dataset.knob; const cur = String((es[k] || {}).current ?? ''); if (el.value !== cur) { try { await api('/api/engine/setting', {method: 'POST', body: {key: k, value: el.tagName === 'SELECT' ? el.value === 'true' : el.value}}); n++; } catch (e2) { toast(k + ': ' + e2.message); } } } toast(`${n} knob(s) applied`, 'ok'); if (n) { refreshState(); views.engine(); } };
    $('#teach-add').onclick = async () => { const t = $('#teach-text').value.trim(); if (!t) return; try { await api('/api/guidance', {method: 'POST', body: {text: t, scope: $('#teach-scope').value}}); pushTrace('teach/add · ' + t.slice(0, 50), 'ok'); views.engine(); } catch (e2) { toast(e2.message); } };
