    const prodHtml = `<div class="panel"><div class="ph"><span class="t">Product cohorts · how each is treated</span><span class="meta">lens · never · cadence · cross-sell</span></div><div class="pb"><div class="cards">${(d.products || []).map(p => `<div class="card"><div class="nm"><span>${esc(p.name)}</span><span class="chip">${p.families || 0} fam · ${p.reach ? fmt(p.reach, 0) : '—'}</span></div><div class="mv">${esc(p.lens)}</div><div style="font-size:11px"><span class="lab10">never</span> ${(p.never || []).map(esc).join(' · ')}</div><div style="font-size:11px;margin-top:3px"><span class="lab10">cadence</span> ${esc(p.cadence)}</div><div class="foot"><span class="lab10">cross-sell</span><span style="text-align:right;font-size:10px">${(p.cross_sell || []).map(esc).join(' · ')}</span></div>${p.click_rate != null ? `<div class="ghost" style="font-size:10px;margin-top:4px">click ${fmt(p.click_rate, 2)}% across ${p.campaigns} campaigns</div>` : ''}</div>`).join('')}</div></div></div>`;
