    body.innerHTML = `${famHtml}<div class="cols"><div class="c2">${peaceHtml}</div><div class="c2">${nsHtml}</div></div>${prodHtml}<div class="cols"><div class="c2">${studiesHtml}</div><div class="c2">${reqHtml}</div></div>`;
